{
  "spec": {
    "app_name": "Coffee Corner",
    "purpose": "A professional coffee shop landing page for customers and employees.",
    "user_roles": [
      "Customer",
      "Employee",
      "Admin"
    ],
    "core_features": [
      "Hero section",
      "Menu items",
      "Contact information",
      "Responsive design"
    ],
    "entities": [
      {
        "name": "Customer",
        "fields": [
          {
            "name": "Name",
            "type": "text",
            "required": true
          },
          {
            "name": "Email",
            "type": "email",
            "required": true
          }
        ]
      },
      {
        "name": "Employee",
        "fields": [
          {
            "name": "Name",
            "type": "text",
            "required": true
          },
          {
            "name": "Email",
            "type": "email",
            "required": true
          }
        ]
      }
    ],
    "relationships": [],
    "auth_required": true,
    "routes_needed": [
      "/",
      "/menu",
      "/contact"
    ],
    "pages_needed": [
      {
        "name": "Home",
        "purpose": "Landing page with hero section and menu items"
      },
      {
        "name": "Menu",
        "purpose": "List of coffee shop menu items"
      },
      {
        "name": "Contact",
        "purpose": "Contact form for customers and employees"
      }
    ],
    "pages": [
      {
        "name": "Home",
        "widgets": []
      },
      {
        "name": "Menu",
        "widgets": []
      },
      {
        "name": "Contact",
        "widgets": []
      }
    ],
    "navigation": [],
    "dashboard_kpis": [],
    "database_requirements": [
      {
        "table_name": "Customers",
        "fields": ["id", "name", "email"]
      },
      {
        "table_name": "Employees",
        "fields": ["id", "name", "email"]
      },
      {
        "table_name": "Menu",
        "fields": ["id", "name", "price"]
      }
    ],
    "validation_requirements": [
      {
        "field": "Customer name",
        "validation": "required"
      },
      {
        "field": "Customer email",
        "validation": "required"
      },
      {
        "field": "Employee name",
        "validation": "required"
      },
      {
        "field": "Employee email",
        "validation": "required"
      }
    ],
    "error_handling_requirements": [],
    "responsive_requirements": [
      {
        "device": "Mobile",
        "resolution": "Portrait",
        "viewport": "375px"
      },
      {
        "device": "Desktop",
        "resolution": "Desktop",
        "viewport": "1280px"
      }
    ],
    "assumptions": [
      "A single local user for authentication",
      "No external integrations required"
    ],
    "theme": {
      "color_scheme": "blue",
      "font_family": "Arial",
      "background_color": "#f0f0f0"
    }
  },
  "steps": [
    "Create a new HTML file and add the required HTML structure for the landing page, menu, and contact forms.",
    "Style the landing page using CSS to create a clean, professional look.",
    "Implement JavaScript to handle form submissions and dynamically update the menu and contact information.",
    "Add authentication functionality to the landing page using JavaScript and a library like Passport.js."
  ]
}
